from pathlib import Path

path = Path("docs/generate_handbook.py")
text = path.read_text(encoding="utf-8")

replacements = {
    "('Resources / Community / Careers','src/pages/ClientFacingPages.jsx','All three are exported from this file.')": "('Resources','src/pages/ResourcesPage.jsx','Starter guides and practical checklists are maintained here.'),\n('Community / Careers','src/pages/ClientFacingPages.jsx','These two pages are exported from this file.')",
    "('Page SEO titles/descriptions','src/data/routeMeta.js','Main page-by-page search titles, descriptions and canonical paths.')": "('Page SEO titles/descriptions','src/data/routeMeta.json','Main page-by-page search titles, descriptions and canonical paths. The build uses the same data to generate static route pages.')",
    "body(doc,'SEO is split between the base page shell and the clean public routes. Page-specific titles, descriptions and canonical paths are stored in src/data/routeMeta.js and applied by src/AppRouter.jsx. Organisation/WebSite structured data is in public/index.html. Search-engine discovery files are public/robots.txt and public/sitemap.xml. Google Search Console should use Domain verification through a TXT record in the eragonova.com DNS settings.')": "body(doc,'SEO is split between the base page shell and the clean public routes. Page-specific titles, descriptions and canonical paths are stored in src/data/routeMeta.json. The React app reads that data through routeMeta.js, and the production build uses the same data to generate real static HTML shells for public routes such as /services/ and /contact/. Organisation/WebSite structured data is in public/index.html. Search-engine discovery files are public/robots.txt and public/sitemap.xml. Google Search Console should use Domain verification through a TXT record in the eragonova.com DNS settings.')",
    "('Change a page search description','src/data/routeMeta.js','Edit the description for the relevant route.')": "('Change a page search description','src/data/routeMeta.json','Edit the description for the relevant route. A new deployment regenerates the matching static route page.')",
    "('Change a page browser/search title','src/data/routeMeta.js','Edit the title for the relevant route.')": "('Change a page browser/search title','src/data/routeMeta.json','Edit the title for the relevant route. A new deployment regenerates the matching static route page.')",
    "body(doc,'The workflow in .github/workflows/deploy-pages.yml runs whenever main changes. It checks out the repository, sets up Node.js, installs packages, runs npm run build, then publishes the build folder to the gh-pages branch using peaceiris/actions-gh-pages.')": "body(doc,'The workflow in .github/workflows/deploy-pages.yml runs whenever main changes. It checks out the repository, sets up Node.js, installs packages, runs npm run build, then publishes the build folder to the gh-pages branch using peaceiris/actions-gh-pages. The postbuild step creates a real index.html inside each main route folder so clean URLs return normal pages instead of relying only on a 404 fallback.')",
    "code(doc,'main branch change  →  npm install  →  npm run build  →  build/  →  gh-pages branch  →  live GitHub Pages website')": "code(doc,'main change → npm install → npm run build → static route shells → build/ → gh-pages → eragonova.com')",
    "('A menu link shows 404','Route missing or route word mismatch','Check AppRouter.jsx and Header.jsx use the same route.')": "('A menu link shows 404','Route metadata/build output missing or route word mismatch','Check routeMeta.json, AppRouter.jsx and the latest deployment. Each public route should have its own generated index.html.')",
    "'I know src/data/routeMeta.js controls page-specific SEO while public/index.html contains the base organisation/social metadata.'": "'I know src/data/routeMeta.json controls page-specific SEO and static clean routes, while public/index.html contains the base organisation/social metadata.'",
    "('Resource library','Makes templates/guides genuinely downloadable and useful.','As original resources are produced.')": "('Resource library expansion','The current Resources page already includes practical starter checklists; add original downloadable templates and deeper guides as they are produced.','Ongoing as original resources are created.')",
    "('13 Oct 2026','Website upgrade','routing / SEO / accessibility / contact','Moved to eragonova.com clean URLs, route SEO, schema, accessibility improvements, analytics readiness and contact-form privacy/spam protection.','Updated after custom-domain launch.')": "('13 Oct 2026','Website upgrade','routing / SEO / accessibility / contact','Moved to eragonova.com clean URLs, route SEO, schema, accessibility improvements, analytics readiness and contact-form privacy/spam protection.','Updated after custom-domain launch.'),('13 Oct 2026','SEO route hardening','routeMeta.json / postbuild / Resources','Generated real static HTML shells for clean routes and added six practical starter checklists to Resources.','Improves indexing, sharing metadata and usefulness.')",
}

for old, new in replacements.items():
    if old not in text:
        print(f"Handbook static-route patch note: pattern not found: {old[:90]}")
    text = text.replace(old, new)

path.write_text(text, encoding="utf-8")
print("Updated handbook generator for static clean routes and the expanded Resources page.")
